    /* --- LocalStorage + Window.name Fallback Helpers (Works on HTTP, file://, and offline about:blank) --- */
    function getFallbackStore() {
      try {
        if (window.name && window.name.startsWith('__NABD_STORE__:')) {
          return JSON.parse(window.name.slice('__NABD_STORE__:'.length));
        }
      } catch (e) {}
      return {};
    }

    function setFallbackStore(obj) {
      try {
        window.name = '__NABD_STORE__:' + JSON.stringify(obj);
      } catch (e) {}
    }

    function safeStorageGet(key, fallback) {
      try {
        const raw = window.localStorage.getItem(key);
        if (raw !== null) return JSON.parse(raw);
      } catch (e) {}
      const fb = getFallbackStore();
      return (key in fb) ? fb[key] : fallback;
    }

    function safeStorageSet(key, val) {
      try {
        window.localStorage.setItem(key, JSON.stringify(val));
      } catch (e) {}
      const fb = getFallbackStore();
      fb[key] = val;
      setFallbackStore(fb);
    }

    function safeStorageRemove(key) {
      try {
        window.localStorage.removeItem(key);
      } catch (e) {}
      const fb = getFallbackStore();
      delete fb[key];
      setFallbackStore(fb);
    }

    function loadPersistedCustomCases() {
      const savedCases = safeStorageGet(STORAGE_KEYS.CUSTOM_CASES, {});
      Object.keys(savedCases).forEach(cid => {
        const c = savedCases[cid];
        if (!c.image) c.image = CASE_IMAGES.img0;
        CASES_DB[cid] = c;
      });
    }

    function saveCustomCaseToStorage(caseObj) {
      const savedCases = safeStorageGet(STORAGE_KEYS.CUSTOM_CASES, {});
      const copy = JSON.parse(JSON.stringify(caseObj));
      delete copy.image; // Resolve CASE_IMAGES.img0 on load to keep storage compact
      savedCases[copy.id] = copy;
      safeStorageSet(STORAGE_KEYS.CUSTOM_CASES, savedCases);
    }

    function getAccountFromStorageOrDefault(accId) {
      const map = safeStorageGet(STORAGE_KEYS.ACCOUNTS_MAP, {});
      if (map[accId]) return JSON.parse(JSON.stringify(map[accId]));
      if (DEMO_ACCOUNTS[accId]) return JSON.parse(JSON.stringify(DEMO_ACCOUNTS[accId]));
      return null;
    }

    function saveAccountToStorage(accObj) {
      if (!accObj || !accObj.id) return;
      const map = safeStorageGet(STORAGE_KEYS.ACCOUNTS_MAP, {});
      map[accObj.id] = JSON.parse(JSON.stringify(accObj));
      safeStorageSet(STORAGE_KEYS.ACCOUNTS_MAP, map);
    }

    function nbPasswordSalt() {
      if (!window.crypto?.getRandomValues) throw new Error('تعذر إنشاء كلمة المرور بهذا المتصفح.');
      const bytes = new Uint8Array(16);
      window.crypto.getRandomValues(bytes);
      return Array.from(bytes, b => b.toString(16).padStart(2, '0')).join('');
    }

    async function nbPasswordDigest(password, saltHex) {
      if (!window.crypto?.subtle) throw new Error('ميزة التحقق من كلمة المرور غير متاحة بهذا المتصفح.');
      const salt = new Uint8Array((saltHex.match(/.{2}/g) || []).map(pair => parseInt(pair, 16)));
      const key = await window.crypto.subtle.importKey('raw', new TextEncoder().encode(password), 'PBKDF2', false, ['deriveBits']);
      const bits = await window.crypto.subtle.deriveBits({ name: 'PBKDF2', salt, iterations: 120000, hash: 'SHA-256' }, key, 256);
      return Array.from(new Uint8Array(bits), b => b.toString(16).padStart(2, '0')).join('');
    }

    function getScratchpadKey(userId, caseId) {
      return `${userId || 'guest'}__${caseId || 'default'}`;
    }

    function saveScratchpadText(text) {
      if (!authState.user) return;
      const pads = safeStorageGet(STORAGE_KEYS.SCRATCHPADS, {});
      pads[getScratchpadKey(authState.user.id, activeCaseId)] = text;
      safeStorageSet(STORAGE_KEYS.SCRATCHPADS, pads);
    }

    function loadScratchpadText(userId, caseId) {
      const pads = safeStorageGet(STORAGE_KEYS.SCRATCHPADS, {});
      return pads[getScratchpadKey(userId, caseId)] || '';
    }

    /* Utility: Format elapsed session timestamp MM:SS */
    function getSessionTimestamp() {
      if (!simState.startTimeMs) return '00:01';
      const elapsedSec = Math.max(1, Math.floor((Date.now() - simState.startTimeMs) / 1000));
      const mins = String(Math.floor(elapsedSec / 60)).padStart(2, '0');
      const secs = String(elapsedSec % 60).padStart(2, '0');
      return `${mins}:${secs}`;
    }

    
    function showToast(msg) {
      const el = document.getElementById('calm-toast');
      const txt = document.getElementById('calm-toast-text');
      if (!el || !txt) return;
      txt.textContent = msg;
      el.classList.remove('hidden');
      clearTimeout(window._toastTimer);
      window._toastTimer = setTimeout(() => el.classList.add('hidden'), 4500);
    }

    function getRoleArabicName(roleCode) {
      if (roleCode === 'professor' || roleCode === 'doctor') return 'أستاذ جامعي';
      if (roleCode === 'practitioner') return 'ممارس صحي';
      return 'طالب جامعي';
    }

    /* Update Headers, Sidebar, Footer, Home Role Sections & Profile UI */
    function syncAuthShellUI() {
      const isAuth = Boolean(authState.isAuthenticated && authState.user);
      const pubHeader = document.getElementById('public-header');
      const appHeader = document.getElementById('app-header');
      const sideGuestNav = document.getElementById('sidebar-guest-nav');
      const sideAppNav = document.getElementById('sidebar-app-nav');
      const sideGuestFoot = document.getElementById('sidebar-guest-footer');
      const sideAppFoot = document.getElementById('sidebar-app-footer');
      const footGuest = document.getElementById('footer-guest-links');
      const footApp = document.getElementById('footer-app-links');
      const sideSub = document.getElementById('sidebar-subtitle');

      pubHeader?.classList.toggle('hidden', isAuth);
      appHeader?.classList.toggle('hidden', !isAuth);
      sideGuestNav?.classList.toggle('hidden', isAuth);
      sideAppNav?.classList.toggle('hidden', !isAuth);
      sideGuestFoot?.classList.toggle('hidden', isAuth);
      sideAppFoot?.classList.toggle('hidden', !isAuth);
      footGuest?.classList.toggle('hidden', isAuth);
      footApp?.classList.toggle('hidden', !isAuth);

      if (!isAuth) {
        if (sideSub) sideSub.textContent = 'تصفح التعريف بالمنصة';
        closeAccountDropdown();
        return;
      }

      const u = authState.user;
      const roleAr = u.roleNameAr || getRoleArabicName(u.role);
      const specAr = u.specialty || 'التمريض';
      const isProf = (u.role === 'professor' || u.role === 'doctor');
      const isStudent = (u.role === 'student');

      if (sideSub) sideSub.textContent = `${roleAr} · ${specAr}`;

      // Update App Header Avatar & Account Dropdown
      const avatarFallback = document.getElementById('user-avatar-fallback');
      if (avatarFallback) avatarFallback.textContent = u.initials || u.name.slice(0, 2);
      const shortNameEl = document.getElementById('header-user-short-name');
      if (shortNameEl) shortNameEl.textContent = u.name;
      const dropName = document.getElementById('dropdown-user-name');
      if (dropName) dropName.textContent = u.name;
      const dropRole = document.getElementById('dropdown-user-role');
      if (dropRole) dropRole.textContent = `${roleAr} (${specAr})`;
      const dropDemo = document.getElementById('dropdown-demo-badge');
      if (dropDemo) {
        dropDemo.textContent = 'وضع العرض التجريبي';
        dropDemo.classList.toggle('hidden', !u.isDemo);
      }

      // Update Sidebar Academic Role Badge
      const uniRolePill = document.getElementById('side-uni-role-pill');
      const uniDesc = document.getElementById('side-uni-desc');
      if (uniRolePill && uniDesc) {
        if (isProf) {
          uniRolePill.textContent = 'صلاحية أستاذ جامعي';
          uniDesc.textContent = 'إدارة نتائج طلبة الشعبة وإضافة حالات سريرية جديدة.';
        } else {
          uniRolePill.textContent = `صلاحية ${roleAr}`;
          uniDesc.textContent = 'استعراض الواجبات السريرية المسندة لك في المساقات الجامعية.';
        }
      }

      // Update Home Welcome Card
      const hwRole = document.getElementById('home-welcome-role');
      if (hwRole) hwRole.textContent = u.roleLabel || `${roleAr} · ${specAr}`;
      const hwDemo = document.getElementById('home-demo-indicator');
      if (hwDemo) {
        hwDemo.textContent = `حساب تجريبي`;
        hwDemo.classList.toggle('hidden', !u.isDemo);
      }
      const hwName = document.getElementById('home-welcome-name');
      if (hwName) hwName.textContent = `أهلاً بك، ${u.name}`;
      const hwSub = document.getElementById('home-welcome-sub');
      if (hwSub) {
        hwSub.textContent = isProf
          ? 'تابع تقارير الطلبة أو أسند حالة جديدة.'
          : 'ابدأ بحالة طوارئ أو اختر تخصصاً للتدرب.';
      }

      // Toggle Role-Specific Home Sections (Professor Dashboard vs Student University Sessions)
      const profHomeSec = document.getElementById('home-professor-section');
      if (profHomeSec) profHomeSec.classList.toggle('hidden', !isProf);

      const stuHomeUniSec = document.getElementById('home-student-uni-section');
      if (stuHomeUniSec) stuHomeUniSec.classList.toggle('hidden', !isStudent);

      renderProfileView();
      renderUniversityPortalByRole();
      renderProfessorCohortTables();
      renderHomePath(u);
    }

    /* Protected Navigation Guard */
    function navigateTo(viewId, options = {}) {
      const isAuth = Boolean(authState.isAuthenticated && authState.user);

      if (PROTECTED_VIEWS.has(viewId) && !isAuth) {
        currentView = 'index';
        showOnlySection('index');
        closeSidebar();
        openAuthModal('login', 'يرجى تسجيل الدخول للوصول إلى مساحة التدريب السريري.');
        try { history.replaceState(null, '', window.location.pathname); } catch (e) {}
        return false;
      }

      currentView = viewId;
      showOnlySection(viewId);

      document.querySelectorAll('.app-nav-btn').forEach(btn => {
        const bView = btn.getAttribute('data-app-view');
        const isActive = bView === viewId && !options.scrollToCases;
        btn.classList.toggle('active', isActive);
      });

      if (viewId === 'coach') {
        renderInteractiveCoachView();
      }

      // Handle Debrief: ONLY show report if SBAR was submitted in the current session!
      if (viewId === 'debrief') {
        const emptyEl = document.getElementById('debrief-empty-state');
        const repEl = document.getElementById('debrief-report-content');
        if (hasCompletedSessionInRun && simState.sessionCompleted && simState.sbarSubmitted) {
          emptyEl?.classList.add('hidden');
          repEl?.classList.remove('hidden');
        } else {
          emptyEl?.classList.remove('hidden');
          repEl?.classList.add('hidden');
        }
      }

      closeSidebar();
      closeAccountDropdown();

      if (options.scrollToCases && viewId === 'home') {
        setTimeout(() => {
          const ca = document.getElementById('home-cases-anchor');
          const anchor = (ca && ca.classList.contains('hidden')) ? document.getElementById('home-nurse') : ca;
          if (anchor) anchor.scrollIntoView({ behavior: 'smooth' });
        }, 60);
      } else if (viewId === 'sim') {
        window.scrollTo({ top: 0, behavior: 'auto' });
        const chatInput = document.getElementById('sim-chat-input');
        if (chatInput && window.innerWidth >= 1024) chatInput.focus();
      } else {
        window.scrollTo({ top: 0, behavior: 'smooth' });
      }

      return true;
    }

    function showOnlySection(viewId) {
      ['index', 'home', 'sim', 'debrief', 'coach', 'profile', 'university', 'observe', 'nurse', 'resp'].forEach(v => {
        const sec = document.getElementById('view-' + v);
        if (sec) sec.classList.toggle('hidden', v !== viewId);
      });
      const footer = document.getElementById('site-footer');
      if (footer) footer.classList.toggle('hidden', viewId === 'sim' || viewId === 'nurse' || viewId === 'observe' || viewId === 'resp');
      if (viewId === 'profile' && authState.user) { try { renderProfileView(); } catch (e) { console.error(e); } }
    }

    /* Login & Logout Actions with Strict Account Isolation */
    function loginWithAccount(accountObj, toastText, targetView = 'home') {
      const stored = getAccountFromStorageOrDefault(accountObj.id) || JSON.parse(JSON.stringify(accountObj));
      authState.isAuthenticated = true;
      authState.user = stored;
      saveAccountToStorage(stored);
      safeStorageSet(STORAGE_KEYS.ACTIVE_USER_ID, stored.id);

      hasCompletedSessionInRun = false;
      simState.sessionCompleted = false;
      simState.sbarSubmitted = false;

      syncAuthShellUI();
      closeAuthModal();
      navigateTo(targetView);
      if (toastText) showToast(toastText);
    }

    // Demo entry for judges: signs in a ready account without registration.
    // Students get a placement matching their year so the level quiz does not
    // interrupt the demo; the professor lands on the university dashboard.
    function nbDemoLogin(id) {
      const acc = DEMO_ACCOUNTS[id];
      if (!acc) return;
      const track = nbTrackOf(acc);
      if (track) {
        const key = NB_PLACEMENT_KEY + '_' + acc.id;
        if (!safeStorageGet(key, null)) {
          const level = nbDerivedLevel(acc);
          safeStorageSet(key, { track, level, pct: parseInt(acc.stats?.avgSpec, 10) || 0, weak: [], rooms: nbPickRooms(level, [], level, track), demo: true, ts: Date.now() });
        }
      }
      loginWithAccount(JSON.parse(JSON.stringify(acc)), `دخول تجريبي: ${acc.name}`, acc.role === 'professor' ? 'university' : 'home');
    }

    function logoutUser() {
      authState.isAuthenticated = false;
      authState.user = null;
      hasCompletedSessionInRun = false;
      simState.sessionCompleted = false;
      simState.sbarSubmitted = false;
      try {
        safeStorageRemove(STORAGE_KEYS.ACTIVE_USER_ID);
        safeStorageRemove(STORAGE_KEYS.ACTIVE_SIM);
      } catch (e) {}
      closeAccountDropdown();
      closeSidebar();
      syncAuthShellUI();
      navigateTo('index');
      showToast('تم تسجيل الخروج والعودة إلى الصفحة التعريفية العامة.');
    }

    function openAuthModal(defaultTab = 'login', noticeMessage = '', focusSelector = '') {
      closeSidebar();
      closeAccountDropdown();
      const modal = document.getElementById('auth-modal');
      const errBox = document.getElementById('login-error-msg');
      const regErr = document.getElementById('reg-error-msg');
      if (!modal) return;
      if (errBox) {
        if (noticeMessage) {
          errBox.textContent = noticeMessage;
          errBox.classList.remove('hidden');
        } else {
          errBox.classList.add('hidden');
        }
      }
      if (regErr) regErr.classList.add('hidden');
      switchAuthModalTab(defaultTab);
      modal.classList.remove('hidden');
      modal.classList.add('flex');
      window.setTimeout(() => {
        // A focusSelector (e.g. the demo accounts) avoids focusing a text field,
        // so phones do not open the keyboard over the options.
        const target = focusSelector
          ? document.querySelector(focusSelector)
          : defaultTab === 'register' ? document.getElementById('reg-name') : document.getElementById('login-email');
        target?.focus({ preventScroll: !focusSelector });
      }, 0);
    }

    function closeAuthModal() {
      const modal = document.getElementById('auth-modal');
      if (!modal) return;
      modal.classList.add('hidden');
      modal.classList.remove('flex');
    }


